import{_ as a,o as e,c as s,a0 as i}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Kỹ năng: /wire & /grill-wire","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/wire.md","filePath":"references/skills/wire.md"}'),t={name:"references/skills/wire.md"};function l(p,n,o,c,r,d){return e(),s("div",null,[...n[0]||(n[0]=[i(`<h1 id="ky-nang-wire-grill-wire" tabindex="-1">Kỹ năng: <code>/wire</code> &amp; <code>/grill-wire</code> <a class="header-anchor" href="#ky-nang-wire-grill-wire" aria-label="Permalink to &quot;Kỹ năng: \`/wire\` &amp; \`/grill-wire\`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>wire</code>, <code>grill-wire</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/wire</code> và <code>/grill-wire</code>.</li><li>Chạy ở Phase 3, sau khi cả Frontend Prototype (2a) và Backend API (2c) đã hoàn thiện.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc lại đặc tả giao diện (<code>ir/design.yaml</code>) và API Spec.</li><li>Đọc Source code Frontend (đang dùng API Mock).</li><li>Các tag đánh dấu dời lại tích hợp như <code>#wire-only:*</code> hoặc <code>#update:*</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li><strong><code>/wire</code></strong>: Tháo bỏ 100% các API Mock/Stub ở phía giao diện Frontend. Đấu nối trực tiếp vào API Backend thật.</li><li>Khắc phục các lỗi về CORS, sai lệch contract dữ liệu (nếu có) giữa FE và BE.</li><li>Xóa bỏ các tag <code>#update:*</code> và <code>#wire-only:*</code> để chốt sổ tính năng.</li><li><strong><code>/grill-wire</code></strong>: Đóng vai trò kiểm thử lại luồng tích hợp (Integration testing), soi xem dữ liệu từ BE trả ra hiển thị trên FE có khớp với Business Spec ban đầu không.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Nằm ở <strong>Phase 3 (Wire - Hội tụ)</strong>.</li><li>Đây là điểm &quot;hội tụ&quot; (Converge) của dây chuyền sản xuất: Lúc trước FE và BE được phát triển song song rẽ nhánh. Giờ đây cả 2 sẽ đan lại vào nhau.</li><li>Nếu xảy ra mâu thuẫn lớn về Spec giữa FE và BE trong khâu này, hệ thống sẽ đẩy ngược lại về kỹ năng <code>/api-update-spec</code> hoặc <code>/update-spec</code> để làm lại.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wire</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Function slug: {hotel-list}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Inputs:</span></span>
<span class="line"><span>- ir/spec.yaml + testcase YAML (resolve bằng --id)</span></span>
<span class="line"><span>- BE contract / staging response</span></span>
<span class="line"><span>- Prototype hiện tại + danh sách route auth bypass cần restore</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Order:</span></span>
<span class="line"><span>1. Align models/ với API thật</span></span>
<span class="line"><span>2. services/* + $apiFetch + parseApiData</span></span>
<span class="line"><span>3. composables gọi service</span></span>
<span class="line"><span>4. validations nếu 422 cần map</span></span>
<span class="line"><span>5. pages/components bind composable</span></span>
<span class="line"><span>6. Gỡ mock production</span></span>
<span class="line"><span>7. Restore auth/guest/rbac middleware (từ grill-prototype handoff)</span></span>
<span class="line"><span>8. Chạy scoped E2E liên quan</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Rules: 4 tầng Portal; không rename field; mock chỉ test/fallback explicit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Verify: lint/typecheck + scoped E2E — báo exit code (verify-gate)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handoff: /grill-test nếu E2E đã có; gap test → /test</span></span></code></pre></div><hr>`,16)])])}const g=a(t,[["render",l]]);export{u as __pageData,g as default};
